def sign(perm):
    # count cycles of length 2 or more only
    seen, cycles = set(), 0
    for s in range(len(perm)):
        if s in seen:
            continue
        k, length = s, 0
        while k not in seen:
            seen.add(k)
            k = perm[k]
            length += 1
        if length > 1:
            cycles += 1
    return (-1) ** cycles

widget.solution:
def sign(perm):
    seen, c = set(), 0
    for s in range(len(perm)):
        if s in seen:
            continue
        c += 1
        k = s
        while k not in seen:
            seen.add(k)
            k = perm[k]
    return (-1) ** (len(perm) - c)
